:"internal","completion_criteria":"Tugas wajib selesai; pengecualian dicatat dengan alasan.","tasks":[{"title":"Koordinasikan perbaikan","conditional":true},{"title":"Konfirmasi hasil tindak lanjut","conditional":false}]},{"title":"Keputusan sertifikasi","description":"Catat hasil resmi · Bahas langkah berikutnya bila belum disetujui","client_label":"Keputusan sertifikasi","client_visible":true,"waiting_kind":"institution","completion_criteria":"Tugas wajib selesai; pengecualian dicatat dengan alasan.","tasks":[{"title":"Catat hasil resmi","conditional":false},{"title":"Bahas langkah berikutnya bila belum disetujui","conditional":true}]},{"title":"Penyerahan hasil","description":"Sampaikan hasil di luar portal · Tutup proyek","client_label":"Penyerahan hasil","client_visible":true,"waiting_kind":"internal","completion_criteria":"Tugas wajib selesai; pengecualian dicatat dengan alasan.","tasks":[{"title":"Sampaikan hasil di luar portal","conditional":false},{"title":"Tutup proyek","conditional":false}]}]}]$workspace_seed$::jsonb) loop
    insert into public.workspace_services(slug,name) values(service_item->>'slug', service_item->>'name') on conflict(slug) do nothing;
    if not exists(select 1 from public.workflow_templates where service_slug = service_item->>'slug') then
      insert into public.workflow_templates(service_slug,version,status,legal_review_required,published_at) values(service_item->>'slug',1,'published',true,now()) returning id into template_uuid;
      stage_pos := 0;
      for stage_item in select value from jsonb_array_elements(service_item->'stages') loop
        stage_pos := stage_pos + 1;
        insert into public.workflow_template_steps(template_id,position,title,description,client_label,client_visible,waiting_kind,completion_criteria)
        values(template_uuid,stage_pos,stage_item->>'title',stage_item->>'description',stage_item->>'client_label',(stage_item->>'client_visible')::boolean,stage_item->>'waiting_kind',stage_item->>'completion_criteria') returning id into step_uuid;
        task_pos := 0;
        for task_item in select value from jsonb_array_elements(stage_item->'tasks') loop
          task_pos := task_pos + 1;
          insert into public.workflow_template_tasks(step_id,position,title,conditional) values(step_uuid,task_pos,task_item->>'title',(task_item->>'conditional')::boolean);
        end loop;
      end loop;
    end if;
  end loop;
  insert into public.priority_offerings(singleton,enabled,title,description,commitment,limitations,terms,price_idr)
  values(true,false,'Layanan Prioritas Penanganan VERALEX','Penanganan internal VERALEX sesuai kelayakan layanan.','Tindak lanjut internal sesuai kesepakatan tertulis.','Tidak mempercepat keputusan atau proses instansi pemerintah.','Pembayaran menunggu penyedia resmi.',0) on conflict(singleton) do nothing;
end $$;
